"""Locations of supplied mission data and products generated by this run."""

from __future__ import annotations

import os
from pathlib import Path


PYTHON_ROOT = Path(__file__).resolve().parents[1]
DATA_ROOT = Path(
    os.environ.get("L1_GEO_DATA_DIR", PYTHON_ROOT / "data")
).expanduser().resolve()
OUTPUT_ROOT = Path(
    os.environ.get("L1_GEO_OUTPUT_DIR", PYTHON_ROOT / "output")
).expanduser().resolve()
PROCESSED_DIR = OUTPUT_ROOT / "processed"
RESULTS_DIR = OUTPUT_ROOT / "results"
FIGURE_DIR = OUTPUT_ROOT / "figures"
DIAGNOSTIC_DIR = FIGURE_DIR / "diag"
